import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;
import org.junit.Before;
import org.junit.After;

import org.apache.commons.lang.NumberUtils;

public class NumberUtilsTest {

    private static NumberUtils createNumberInstance() {
        return new NumberUtils.createInteger(0);
    }

    @Before
    public void setup() {
        Object numInstance = createNumberInstance();
        assertNotNull(numInstance);
    }

    @Rule(JUnit4 JUnit4, String ruleName) {
        @Before("test that the instance is constructed correctly")
        public void testConstructiveness() throws NumberFormatException {
            assertEquals(createNumber(null), null);
            assertTrue(createNumber(-0.5L).equals(NumberUtils.createFloat("-0.5"));
            assertFalse(createNumber(2e-3L).equals(NumberUtils.createDouble(2e-3));
            assertNotNull(NumberUtils.createLong(111111111L));
            assertEqual(createNumber(111111111L).longValue(), 111111111);
        }
    }

    @Before
    public void beforeConstraints() throws NumberFormatException {
        // No additional constraints as the method handles all cases.
    }

    @Test(expected = createNumber(0))
    public void testCreateIntegerZero() {
        assertEquals(createNumberInstance(), 0L);
    }

    @Test(expected = NumberUtils.createFloat(-0.5))
    public void testCreateFloatMinusHalf() {
        assertEquals(NumberUtils.createFloat("-0.5"), -0.5f);
    }

    @Test
    public void testPositiveLargeLongAndBigInteger() throws NumberFormatException {
        assertNotNull(createNumber(1e9L));
        assertNotNull(createNumber(BigInteger.valueOf("2147483647"));
    }
}

public class TestFour {
    public static void main(String[] args) {
        new NumberUtilsTest();
        System.out.println(new NumberUtils.createInteger(0).intValue());
        System.out.println(new NumberUtils.createFloat("-0.5").floatValue());
    }
}
